library;

import 'agent_message.dart';
import 'chain_loop_guard.dart';
import 'messaging_config.dart';

/// Why a wake was refused (null when the wake is allowed).
final class InboxWakeDecision {
  const InboxWakeDecision({
    required this.lane,
    required this.wake,
    required this.countsAgainstCap,
    this.refusalReason,
    this.pauseReason,
  });

  /// Which lane the pending batch was classified into.
  final InboxWakeLane lane;

  /// Whether the host may start a turn.
  final bool wake;

  /// Whether an allowed wake consumes one unit of the chatter cap.
  final bool countsAgainstCap;

  /// Why the wake was refused — persisted in the wake receipts.
  final String? refusalReason;

  /// The pause bound that fired (issue #2226): `cap` (the legacy streak),
  /// `loop` / `budget` (the smart chain guard). Receipts distinguish
  /// `wake_refused` (legacy cap) from `chain_paused:<reason>`; hosts use
  /// it to pick the digest card.
  final String? pauseReason;
}

/// The wake lane a pending batch was classified into (gh-1180).
enum InboxWakeLane {
  /// User input (typed line, attached client, hub user mail): always
  /// wakes; the delivery resets the streak.
  userInput,

  /// A delivered scheduled self-reminder: exempt from the chatter cap,
  /// cadence-floored against a disguised busy-spin.
  scheduledSelf,

  /// Foreign agent-to-agent chatter, and a plugin-only pending batch (no
  /// fabric mail): capped by the same anti-storm budget.
  chatter,
}

const _useDefaultChainGuard = Object();

ChainLoopGuard _defaultChainLoopGuard() {
  const config = MessagingConfig();
  const detection = ChainLoopDetectionConfig();
  return ChainLoopGuard(
    similarityThreshold: detection.similarityThreshold,
    stuckRounds: detection.stuckRounds,
    budgetTokens: config.chainBudgetTokens,
    enabled: detection.enabled,
  );
}

/// The idle inbox-wake lane policy (gh-1180, reworked by issue #2226).
///
/// The hosts' idle inbox watchers (CLI, app) start a turn when mail
/// arrives while idle. Three protections share that gate:
///
/// - the user-input guarantee: mail of kind [AgentMessageKind.user] IS
///   the user talking and must always wake — its delivery resets the
///   streak, so gating it on the counter would deadlock
///   (no run → no reset → no run);
/// - the smart chain guard ([chainGuard], issue #2226): the DEFAULT
///   bound — loop detection (content-similarity + no-progress signals)
///   and an autonomous-chain token budget pause a looping or runaway
///   chain with a user-facing digest, while productive long
///   collaborations (fresh ids/state every round) never trigger;
/// - the LEGACY chatter cap ([maxStreak]): the raw consecutive-wake
///   counter, now **OFF by default** (0) — volume is not looping, and
///   the money-project incident (10 productive exchanges refused) is the
///   pinned regression. A positive `messaging.wakeChatterCap` re-enables
///   the pre-#2226 behavior verbatim.
///
/// gh-1180's third lane: a delivered `schedule_message` self-reminder
/// (`[scheduled] ` prefix, from == to == the recipient's own mailbox) is
/// a DELIBERATE, agent-chosen cadence — a night watch, a periodic sweep,
/// a delayed follow-up — not chatter. It is EXEMPT from every bound so a
/// self-chain wakes forever, with one guard when the legacy cap is on:
/// wakes arriving faster than [scheduledSelfCadenceFloor] are a
/// busy-spin disguised as self-scheduling (a zero-delay re-schedule
/// loop) and count against the ordinary cap, bounding the storm exactly
/// like foreign chatter. With the cap OFF (default) the spin is bounded
/// by the chain guard's budget instead.
///
/// Configured hosts should construct through [InboxWakePolicy.forConfig].
/// Bare cap-off construction gets a fresh guard from [MessagingConfig]'s
/// defaults; only explicit `chainGuard: null` selects an unbounded gate.
final class InboxWakePolicy {
  /// [chainGuard] accepts a [ChainLoopGuard] or null. Its widened static
  /// type is intentional: Dart otherwise cannot distinguish an omitted
  /// nullable argument from an explicit null. Omitted installs the safe
  /// defaults when the legacy cap is off; explicit null remains the visible
  /// unbounded opt-out, and a bare positive cap keeps its legacy behavior.
  InboxWakePolicy({
    int maxStreak = defaultMaxInboxWakeStreak,
    this.scheduledSelfCadenceFloor = defaultScheduledSelfCadenceFloor,
    Object? chainGuard = _useDefaultChainGuard,
    this.clock,
  }) : maxStreak = maxStreak,
       chainGuard = identical(chainGuard, _useDefaultChainGuard)
           ? maxStreak == 0
                 ? _defaultChainLoopGuard()
                 : null
           : chainGuard as ChainLoopGuard?;

  /// The one construction from a `messaging:` section (issue #2226): the
  /// guard rides [chainGuard], the legacy cap from `wakeChatterCap`.
  factory InboxWakePolicy.forConfig(
    MessagingConfig config,
    ChainLoopGuard guard,
  ) => InboxWakePolicy(maxStreak: config.wakeChatterCap, chainGuard: guard);

  /// The legacy anti-storm cap for foreign agent-to-agent chatter.
  /// `0` (the issue #2226 default) disables the cap entirely; hosts
  /// wire `messaging.wakeChatterCap` here (10 was the pre-#2226 value).
  static const int defaultMaxInboxWakeStreak = 0;

  /// Wakes closer together than this are a spin, not a cadence (gh-1180
  /// E5): the exemption must not open a busy-spin.
  static const Duration defaultScheduledSelfCadenceFloor = Duration(
    seconds: 30,
  );

  /// Consecutive chatter wakes allowed without user input. `0` (the
  /// issue #2226 default) disables the cap — [chainGuard] is the bound.
  final int maxStreak;

  /// The smart chain guard (issue #2226): loop detection + the
  /// autonomous-chain token budget. Bare construction with the cap off
  /// installs [MessagingConfig]'s defaults. Explicit `chainGuard: null`
  /// keeps bare cap gating (an intentional no-bound opt-out when
  /// [maxStreak] is 0). The guard rides THIS policy's user-input reset so
  /// the two cannot drift apart.
  final ChainLoopGuard? chainGuard;

  /// Minimum spacing between two EXEMPT scheduled-self wakes; anything
  /// faster counts against the cap. Mutable so a host test can collapse
  /// it (zero: every self wake exempt) or exercise the spin guard.
  Duration scheduledSelfCadenceFloor;

  /// Injectable clock (tests); null uses [DateTime.now].
  final DateTime Function()? clock;

  DateTime _now() => clock?.call() ?? DateTime.now();

  /// Consecutive inbox-triggered wakes without user input.
  int streak = 0;

  bool _refusalAnnounced = false;

  DateTime? _lastScheduledSelfWakeAt;

  /// A delivered user-kind message (or a typed line) IS the user talking.
  /// Ends the refusal episode too (see [announceRefusal]): the two pieces
  /// of episode state live side by side so they cannot drift apart.
  /// The chain guard resets with it (issue #2226: the human is watching —
  /// streaks reset, the budget re-arms, pause verdicts clear).
  void resetStreak() {
    streak = 0;
    _refusalAnnounced = false;
    chainGuard?.resetFromUserInput();
  }

  /// Whether THIS call may announce the current refusal: true exactly
  /// once per refusal episode. An episode opens on the first refusal and
  /// closes when the gate reopens — a user-input reset ([resetStreak])
  /// or any allowed cap-consuming (non-exempt) wake. Hosts gate their
  /// visible refusal line AND their refusal receipts on this: the gate
  /// holds until user input arrives, so per-tick announcements would
  /// append ~43k duplicate lines/day to the receipt trail (review: the
  /// wake_attempted spam) and spam the terminal.
  bool announceRefusal() {
    if (_refusalAnnounced) return false;
    _refusalAnnounced = true;
    return true;
  }

  /// Whether [message] is the delivery of a scheduled self-reminder: the
  /// scheduler's `[scheduled] ` prefix addressed from the recipient's own
  /// mailbox (from == to). Foreign chatter cannot produce the shape by
  /// accident — its `fromId` is the sender's mailbox, never mine.
  static bool isScheduledSelfMail(AgentMessage message) =>
      message.fromId == message.toId && message.text.startsWith('[scheduled] ');

  /// Decides — and books — the wake for one pending batch. Call only when
  /// mail is pending and the host is idle; a refused decision leaves the
  /// counters untouched, so the next tick retries under the same rules.
  ///
  /// [pluginPending] classifies a PLUGIN-ONLY batch (an empty [pending]
  /// with a pending plugin-inbox item) as [InboxWakeLane.chatter]: plugin
  /// mail rides the same anti-storm budget as fabric chatter. The flag is
  /// IGNORED when [pending] is non-empty — the fabric lanes own that
  /// classification — so passing it alongside real mail changes nothing.
  InboxWakeDecision wakeDecisionFor(
    List<AgentMessage> pending, {
    bool pluginPending = false,
  }) {
    if (pending.any((message) => message.kind == AgentMessageKind.user)) {
      // The delivery resets the streak (_mainInboxMessages / sendText);
      // the wake itself never blocks on it.
      return const InboxWakeDecision(
        lane: InboxWakeLane.userInput,
        wake: true,
        countsAgainstCap: false,
      );
    }
    if (pending.any(isScheduledSelfMail)) {
      final now = _now();
      final last = _lastScheduledSelfWakeAt;
      final rapid =
          last != null && now.difference(last) < scheduledSelfCadenceFloor;
      _lastScheduledSelfWakeAt = now;
      if (!rapid) {
        // A deliberate cadence (>= floor since the last self wake, or the
        // first after startup): exempt forever — the night-watch lane.
        return const InboxWakeDecision(
          lane: InboxWakeLane.scheduledSelf,
          wake: true,
          countsAgainstCap: false,
        );
      }
      // A storm disguised as self-scheduling (gh-1180 E5): with the cap
      // ON it consumes the legacy streak, exactly like foreign chatter.
      // With the cap OFF it instead consults the chain guard's sticky
      // pause/budget (an empty batch deliberately skips loop similarity).
      // The host books each ALLOWED rapid-spin run's usage, so even a pure
      // scheduled-self loop reaches this bound without chatter traffic.
      if (maxStreak == 0) {
        final pause = chainGuard?.evaluate(const []);
        if (pause != null) {
          return InboxWakeDecision(
            lane: InboxWakeLane.scheduledSelf,
            wake: false,
            countsAgainstCap: false,
            refusalReason: pause.evidence,
            pauseReason: pause.reason.name,
          );
        }
      }
      if (maxStreak > 0 && streak >= maxStreak) {
        return InboxWakeDecision(
          lane: InboxWakeLane.scheduledSelf,
          wake: false,
          countsAgainstCap: true,
          refusalReason:
              'scheduled self-mail is arriving faster than the '
              '${scheduledSelfCadenceFloor.inSeconds}s cadence floor with '
              'the chatter cap exhausted (busy-spin guard) — re-schedule '
              'with a slower delay or send user input to reset',
          pauseReason: 'cap',
        );
      }
      streak++;
      _refusalAnnounced = false;
      return InboxWakeDecision(
        lane: InboxWakeLane.scheduledSelf,
        wake: true,
        countsAgainstCap: true,
      );
    }
    // Foreign agent-to-agent chatter — and a PLUGIN-ONLY batch (no
    // fabric mail pending, see [pluginPending]): the smart chain guard
    // first (issue #2226 — the loop verdict / budget exhaustion pause
    // with a digest, never booking the streak), then the LEGACY cap
    // (default 0 = off; positive `messaging.wakeChatterCap` re-enables).
    final pause = chainGuard?.evaluate(pending);
    if (pause != null) {
      return InboxWakeDecision(
        lane: InboxWakeLane.chatter,
        wake: false,
        countsAgainstCap: false,
        refusalReason: pause.evidence,
        pauseReason: pause.reason.name,
      );
    }
    if (maxStreak > 0 && streak >= maxStreak) {
      return InboxWakeDecision(
        lane: InboxWakeLane.chatter,
        wake: false,
        countsAgainstCap: true,
        refusalReason:
            'inbox-wake streak cap reached ($streak consecutive '
            'agent-kind wakes without user input) — mail stays queued '
            'until the next user input',
        pauseReason: 'cap',
      );
    }
    streak++;
    _refusalAnnounced = false;
    return InboxWakeDecision(
      lane: InboxWakeLane.chatter,
      wake: true,
      countsAgainstCap: true,
    );
  }
}

/// The smart agent↔agent chain guard (issue #2226): replaces the blunt
/// inbox-wake streak cap with EVIDENCE of looping.
///
/// A wake chain (per counterparty pair) tracks:
/// - **Content novelty**: consecutive cross-agent mails compared on
///   normalized text (ids/numbers masked) via local shingle-overlap
///   similarity — no model calls, no network (the documented fallback
///   path IS the implementation; there is no embedding provider in the
///   wake path by the issue's own non-goals).
/// - **Progress signals**: fresh identifiers (new ids/numbers/hashes in
///   the raw text). Templated-but-productive updates carry fresh state
///   every round, so high masked similarity alone is NEVER the verdict —
///   the money-project shape passes.
/// - **Loop verdict**: `stuckRounds` consecutive exchanges that are both
///   near-identical AND carry no fresh state → the chain is LOOPING.
/// - **Budget**: an autonomous-chain token budget (`recordSpend`, fed by
///   the host's turn usage); exhaustion pauses exactly like a verdict.
///
/// A pause is ADVISORY wake-gating only: mail stays queued and visible,
/// delivery semantics are untouched. The host renders the digest
/// ([chainPauseDigestLines]) and offers continue/stop; any delivered user
/// input resets everything (the human is watching).
library;

import 'agent_message.dart';
import 'chain_state_store.dart';

/// Why a chain paused.
enum ChainPauseReason {
  /// Near-identical content with no fresh state across `stuckRounds`.
  loop,

  /// The autonomous-chain token budget is exhausted.
  budget,
}

/// A pause verdict for one wake decision.
final class ChainPause {
  const ChainPause({required this.reason, required this.evidence});

  final ChainPauseReason reason;

  /// The human-readable evidence line ("last 4 exchanges ≥92% similar,
  /// no new ids/files" / "autonomous spend 412000/400000 tokens").
  final String evidence;
}

/// One counterparty pair-window's state.
final class _ChainWindow {
  String prevMasked = '';
  Set<String> prevStateTokens = {};
  int stuckRounds = 0;
  double lastSimilarity = 0;
}

/// The deterministic loop detector + chain budget. Pure — no I/O; the
/// host persists [snapshot]/[restore] via [ChainStateStore].
final class ChainLoopGuard {
  ChainLoopGuard({
    required this.similarityThreshold,
    required this.stuckRounds,
    required this.budgetTokens,
    this.enabled = true,
  }) : assert(stuckRounds >= 1),
       assert(similarityThreshold >= 0 && similarityThreshold <= 1);

  /// Masked-text pairwise similarity above which a no-progress exchange
  /// counts as a stuck round.
  final double similarityThreshold;

  /// Consecutive no-progress rounds before a loop verdict.
  final int stuckRounds;

  /// The autonomous-chain spend bound in tokens; `0` disables.
  final int budgetTokens;

  /// When false, loop verdicts never fire (the budget still does).
  final bool enabled;

  int tokensSpent = 0;

  bool _paused = false;
  ChainPause? _pause;
  final Map<String, _ChainWindow> _windows = {};

  /// Whether the chain is currently paused (sticky until
  /// [continueChain]/[resetFromUserInput]/[stopChain]).
  bool get paused => _paused;

  /// The current pause verdict (null when not paused).
  ChainPause? get pause => _pause;

  /// Whether the chain budget is exhausted.
  bool get budgetExhausted => budgetTokens > 0 && tokensSpent >= budgetTokens;

  /// The host books the wake run's turn usage here. Returns whether the
  /// booking crossed the budget (the NEXT decision pauses).
  void recordSpend(int tokens) {
    if (tokens <= 0 || _paused) return;
    tokensSpent += tokens;
  }

  /// Decides the wake for one pending agent-kind batch. Returns null
  /// (allow) or the pause verdict; a paused guard stays paused — the
  /// host's episode latch gates digest spam.
  ChainPause? evaluate(List<AgentMessage> pending) {
    if (_paused) return _pause;
    if (budgetExhausted) {
      _paused = true;
      return _pause = ChainPause(
        reason: ChainPauseReason.budget,
        evidence:
            'autonomous chain spend $tokensSpent/$budgetTokens tokens '
            'without user input',
      );
    }
    if (!enabled) return null;
    for (final message in pending) {
      if (message.kind != agentKind) continue;
      final pause = _feed(message.fromId, message.text);
      if (pause != null) {
        _paused = true;
        return _pause = pause;
      }
    }
    return null;
  }

  static const agentKind = AgentMessageKind.agent;

  /// Feeds one exchange into [sender]'s pair-window; a loop verdict when
  /// the stuck counter reaches [stuckRounds].
  ChainPause? _feed(String sender, String text) {
    final window = _windows.putIfAbsent(sender, _ChainWindow.new);
    final masked = maskText(normalizeText(text));
    final stateTokens = extractStateTokens(normalizeText(text));
    if (window.prevMasked.isEmpty) {
      // First exchange of the window: arm the comparison, never pause.
      window.prevMasked = masked;
      window.prevStateTokens = stateTokens;
      return null;
    }
    final similarity = shingleSimilarity(window.prevMasked, masked);
    final fresh = stateTokens.difference(window.prevStateTokens).isNotEmpty;
    window.lastSimilarity = similarity;
    if (similarity >= similarityThreshold && !fresh) {
      window.stuckRounds++;
    } else {
      // Genuinely different content OR fresh state: progress resets.
      window.stuckRounds = 0;
    }
    window.prevMasked = masked;
    window.prevStateTokens = stateTokens;
    if (window.stuckRounds >= stuckRounds) {
      return ChainPause(
        reason: ChainPauseReason.loop,
        evidence:
            'last $stuckRounds exchanges with ${senderMailbox(sender)} are '
            '${(similarity * 100).round()}% similar with no new ids/files',
      );
    }
    return null;
  }

  /// A delivered user input IS the user talking: streaks reset, the
  /// budget re-arms, the verdict clears (the human is watching).
  void resetFromUserInput() {
    _paused = false;
    _pause = null;
    tokensSpent = 0;
    _windows.clear();
  }

  /// The user's explicit "continue" on the digest: same reset, kept
  /// distinct for intent.
  void continueChain() => resetFromUserInput();

  /// The user's explicit "stop": the host drops the pending mail; the
  /// guard just clears state so a future chain starts fresh.
  void stopChain() => resetFromUserInput();

  ChainSnapshot snapshot() => ChainSnapshot(
    tokensSpent: tokensSpent,
    windows: {
      for (final MapEntry(key: sender, value: window) in _windows.entries)
        sender: ChainWindowState(
          stuckRounds: window.stuckRounds,
          prevMasked: window.prevMasked,
          prevStateTokens: window.prevStateTokens.toList(),
          lastSimilarity: window.lastSimilarity,
        ),
    },
  );

  void restore(ChainSnapshot snapshot) {
    tokensSpent = snapshot.tokensSpent;
    _windows
      ..clear()
      ..addEntries([
        for (final MapEntry(key: sender, value: state)
            in snapshot.windows.entries)
          MapEntry(
            sender,
            _ChainWindow()
              ..stuckRounds = state.stuckRounds
              ..prevMasked = state.prevMasked
              ..prevStateTokens = state.prevStateTokens.toSet()
              ..lastSimilarity = state.lastSimilarity,
          ),
      ]);
  }

  static String senderMailbox(String sender) => sender;
}

/// Lowercases and collapses whitespace; punctuation is stripped so
/// "Done." and "done" compare equal.
String normalizeText(String text) => text
    .toLowerCase()
    .replaceAll(RegExp(r'[^\w\s]'), ' ')
    .replaceAll(RegExp(r'\s+'), ' ')
    .trim();

/// Masks digit runs (ids, counts, timestamps, hashes all contain digits)
/// so templated updates compare on SHAPE, not on the numbers that changed.
String maskText(String normalized) =>
    normalized.replaceAll(RegExp(r'\d+'), '#');

/// The raw identifiers of one exchange: digit-runs and hex-ish tokens.
/// A round with identifiers the previous round lacked has FRESH STATE —
/// the progress signal that keeps templated-but-productive chains alive.
Set<String> extractStateTokens(String normalized) => {
  for (final token in normalized.split(' '))
    if (token.contains(RegExp(r'\d')) ||
        RegExp(r'^[0-9a-f]{7,}$').hasMatch(token))
      token,
};

/// Jaccard overlap over word 3-grams (texts shorter than 3 words compare
/// as one shingle). 0 = disjoint, 1 = identical.
double shingleSimilarity(String a, String b) {
  final shinglesA = _shingles(a);
  final shinglesB = _shingles(b);
  if (shinglesA.isEmpty && shinglesB.isEmpty) return 1;
  if (shinglesA.isEmpty || shinglesB.isEmpty) return 0;
  final common = shinglesA.intersection(shinglesB).length;
  return common / shinglesA.union(shinglesB).length;
}

Set<String> _shingles(String text) {
  final words = text.split(' ').where((word) => word.isNotEmpty).toList();
  if (words.isEmpty) return {};
  if (words.length < 3) return {words.join(' ')};
  return {
    for (var i = 0; i <= words.length - 3; i++)
      '${words[i]} ${words[i + 1]} ${words[i + 2]}',
  };
}

/// The user-facing pause digest card (both hosts render these lines —
/// AC5: never silent). [pendingCount] is the host's queued-mail count.
List<String> chainPauseDigestLines({
  required ChainPauseReason reason,
  required String evidence,
  required int pendingCount,
  String? counterparty,
}) {
  final title = switch (reason) {
    ChainPauseReason.loop => 'chain paused — loop detected',
    ChainPauseReason.budget => 'chain paused — budget exhausted',
  };
  return [
    '┌─ $title',
    if (counterparty != null) '│ counterparty: $counterparty',
    '│ evidence: $evidence',
    '│ pending mail: $pendingCount message(s) — QUEUED, nothing dropped',
    '│ continue: /chain continue (resets the budget, overrides the verdict)',
    '│ stop: /chain stop (drops the pending mail with a tombstone receipt)',
    '└─ any user input also resumes the chain',
  ];
}

